"""Intent tests for M1-T18: risk.annualize scales daily volatility over trading days (RISK-03)."""

import pytest

from risk import Returns, VolSeries, annualize


def returns_from(payload: dict) -> Returns:
    return Returns(
        base_date=payload["base_date"],
        dates=tuple(payload["dates"]),
        tickers=tuple(payload["tickers"]),
        values={ticker: tuple(values) for ticker, values in payload["values"].items()},
    )


def vol_from(payload: dict) -> VolSeries:
    return VolSeries(
        returns=returns_from(payload["returns"]),
        window=payload["window"],
        annualized=payload["annualized"],
        values={ticker: tuple(values) for ticker, values in payload["values"].items()},
    )


@pytest.mark.intent
def test_tc06_each_value_scaled_by_trading_days_gaps_kept(golden):
    data, expected = golden("risk", "TC-06")
    vol = vol_from(data["vol"])

    result = annualize(vol)

    assert result.annualized is expected["annualized"]
    assert set(result.values) == set(expected["values"])
    for ticker, want in expected["values"].items():
        got = result.values[ticker]
        assert len(got) == len(want)
        for g, w in zip(got, want, strict=True):
            if w is None:
                assert g is None
            else:
                assert g == pytest.approx(w, rel=0, abs=expected["tol"])


@pytest.mark.intent
def test_tc06_keeps_returns_and_window(golden):
    data, _ = golden("risk", "TC-06")
    vol = vol_from(data["vol"])

    result = annualize(vol)

    assert result.returns == vol.returns
    assert result.window == vol.window


@pytest.mark.intent
def test_tc06_leaves_the_input_daily(golden):
    data, _ = golden("risk", "TC-06")
    vol = vol_from(data["vol"])
    before = dict(vol.values)

    annualize(vol)

    assert vol.annualized is False
    assert dict(vol.values) == before


@pytest.mark.intent
def test_annualizing_an_annualized_series_is_a_value_error(contract_sample):
    vol = vol_from(contract_sample("risk.VolSeries"))
    assert vol.annualized is True

    with pytest.raises(ValueError, match="annualized"):
        annualize(vol)


@pytest.mark.intent
def test_annualizing_twice_is_a_value_error(golden):
    data, _ = golden("risk", "TC-06")
    once = annualize(vol_from(data["vol"]))

    with pytest.raises(ValueError, match="annualized"):
        annualize(once)

